import {
  triggerHihat,
  triggerKick,
  triggerSnare,
} from "@/lib/drum-synthesis";
import { createStepPlayer } from "@/lib/step-player";
import { webAudio } from "@/lib/web-audio";
import "@/components/audio-ui/sequencer/web";

const STEPS = 16;
const BPM = 112;
const VOLUME = 0.7;
const ROWS = ["Kick", "Snare", "Hihat"];
const TRIGGERS = [triggerKick, triggerSnare, triggerHihat];
const VELOCITIES = [
  [1, 0.5, 0.7, 0.5, 0.9, 0.5, 0.7, 0.5, 1, 0.5, 0.7, 0.5, 0.9, 0.5, 0.7, 0.6],
  [1, 1, 1, 1, 0.8, 1, 1, 1, 1, 1, 1, 1, 0.85, 1, 1, 0.4],
  [
    0.55, 0.6, 0.9, 0.6, 0.55, 0.6, 0.9, 0.6, 0.55, 0.6, 0.9, 0.6, 0.55, 0.6,
    0.9, 0.6,
  ],
];
const on = (steps: number[]) =>
  Array.from({ length: STEPS }, (_, step) => steps.includes(step));
const BEAT = [on([0, 4, 8, 12]), on([4, 12]), on([2, 6, 10, 14])];
const EMPTY = () => ROWS.map(() => Array.from({ length: STEPS }, () => false));

/** Plays what the pattern holds on a step: each hit goes through a gain of its own, the step's velocity. */
function playStep(rows: boolean[][], levels: number[][], step: number) {
  const ctx = webAudio.resume();
  if (!ctx) {
    return;
  }
  rows.forEach((row, at) => {
    if (!row[step]) {
      return;
    }
    const hit = ctx.createGain();
    hit.gain.value = (levels[at]?.[step] ?? 1) * VOLUME;
    hit.connect(ctx.destination);
    TRIGGERS[at]?.(ctx, hit, ctx.currentTime);
  });
}

/** Draws the sequencer into `element`, and returns what takes it away. The rows, the steps and the velocity bars are made for you: styled here from their tags. */
export function sequencerWebDemo(element: HTMLElement) {
  let pattern = BEAT;
  let velocities = VELOCITIES;
  const player = createStepPlayer({
    bpm: BPM,
    onStep: (step) => playStep(pattern, velocities, step),
    steps: STEPS,
  });

  element.innerHTML = `
    <style>
      audio-ui-sequencer { display: flex; flex-direction: column; gap: 0.375rem; width: 100%; }
      audio-ui-sequencer-row { display: grid; grid-template-columns: repeat(16, minmax(0, 1fr)); gap: 0.25rem; }
      audio-ui-sequencer-cell button { width: 100%; height: 2.25rem; border: 0; border-radius: var(--radius-sm); background: var(--muted); cursor: pointer; }
      audio-ui-sequencer-cell button[aria-pressed="true"] { background: var(--primary); }
      audio-ui-sequencer-cell button[data-current] { outline: 2px solid var(--ring); }
      audio-ui-sequencer-velocity { display: block; position: relative; height: 2rem; cursor: ns-resize; background: linear-gradient(to top, var(--muted-foreground) calc(var(--sequencer-velocity) * 100%), transparent 0); }
    </style>
    <div class="flex w-full flex-col gap-3">
      <audio-ui-sequencer aria-label="Drum pattern" velocity-bars velocities='${JSON.stringify(velocities)}' value='${JSON.stringify(pattern)}'></audio-ui-sequencer>
      <div class="flex items-center justify-between gap-2">
        <button class="inline-flex h-8 items-center rounded-md border bg-background px-3 text-sm hover:bg-muted" data-action="toggle" type="button">Play</button>
        <button class="inline-flex h-8 items-center rounded-md px-3 text-sm hover:bg-muted" data-action="clear" type="button">Clear</button>
      </div>
    </div>`;
  const grid = element.querySelector("audio-ui-sequencer") as
    | (HTMLElement & { source?: unknown })
    | null;
  if (grid) {
    grid.source = player.source;
  }
  const onInput = (event: Event) => {
    pattern = (event as CustomEvent).detail.value;
  };
  const onClick = (event: Event) => {
    const action = (event.target as HTMLElement)
      .closest("[data-action]")
      ?.getAttribute("data-action");
    if (action === "toggle") {
      if (player.isPlaying()) {
        player.stop();
      } else {
        player.start();
      }
      const button = element.querySelector('[data-action="toggle"]');
      if (button) {
        button.textContent = player.isPlaying() ? "Stop" : "Play";
      }
    } else if (action === "clear") {
      pattern = EMPTY();
      if (grid) {
        grid.setAttribute("value", JSON.stringify(pattern));
      }
    }
  };
  const onVelocity = (event: Event) => {
    velocities = (event as CustomEvent).detail.value;
  };
  grid?.addEventListener("input", onInput);
  grid?.addEventListener("velocitychange", onVelocity);
  element.addEventListener("click", onClick);
  return () => {
    player.stop();
    grid?.removeEventListener("input", onInput);
    grid?.removeEventListener("velocitychange", onVelocity);
    element.removeEventListener("click", onClick);
    element.innerHTML = "";
  };
}
